fastapi-app.app/service.py:
from app.models import Note


class NoteStore:
    def __init__(self) -> None:
        self._items: dict[int, Note] = {}
        self._next_id = 1

    def create(self, title: str, body: str = "") -> Note:
        note = Note(id=self._next_id, title=title, body=body)
        self._items[note.id] = note
        self._next_id += 1
        return note

    def list(self) -> list[Note]:
        return list(self._items.values())

    def get(self, note_id: int) -> Note | None:
        return self._items.get(note_id)

fastapi-app.app/main.py:
from fastapi import FastAPI

from app.service import NoteStore

app = FastAPI()
store = NoteStore()


@app.get("/notes")
def list_notes():
    return [{"id": n.id, "title": n.title} for n in store.list()]


@app.post("/notes")
def create_note(payload: dict):
    note = store.create(payload["title"], payload.get("body", ""))
    return {"id": note.id, "title": note.title}

